import { EventEmitter } from 'events';
import * as crypto from 'crypto';

interface FirmwareChunk {
  offset: number;
  data: Buffer;
  checksum: string;
}

interface DeviceContext {
  deviceId: string;
  firmwareSlot: Buffer;
  processingState: 'idle' | 'receiving' | 'validating' | 'applying';
  chunkMap: Map<number, FirmwareChunk>;
  totalSize: number;
  receivedSize: number;
}

class FirmwareProcessor extends EventEmitter {
  private devices: Map<string, DeviceContext> = new Map();
  private validationQueue: Array<{ ctx: DeviceContext; resolve: (v: boolean) => void }> = [];
  private processingInterval: NodeJS.Timer | null = null;

  constructor() {
    super();
    this.processingInterval = setInterval(() => this.drainValidationQueue(), 100);
  }

  allocateDevice(deviceId: string, maxFirmwareSize: number): DeviceContext {
    const ctx: DeviceContext = {
      deviceId,
      firmwareSlot: Buffer.alloc(maxFirmwareSize),
      processingState: 'idle',
      chunkMap: new Map(),
      totalSize: maxFirmwareSize,
      receivedSize: 0,
    };
    this.devices.set(deviceId, ctx);
    return ctx;
  }

  async uploadChunk(deviceId: string, chunk: FirmwareChunk): Promise<boolean> {
    const ctx = this.devices.get(deviceId);
    if (!ctx) return false;
    if (ctx.processingState === 'applying') return false;

    const expectedChecksum = crypto
      .createHash('sha256')
      .update(chunk.data)
      .digest('hex');
    if (expectedChecksum !== chunk.checksum) return false;

    if (chunk.offset + chunk.data.length > ctx.totalSize) return false;

    ctx.processingState = 'receiving';
    chunk.data.copy(ctx.firmwareSlot, chunk.offset);
    ctx.chunkMap.set(chunk.offset, chunk);
    ctx.receivedSize += chunk.data.length;

    if (ctx.receivedSize >= ctx.totalSize) {
      return this.beginValidation(ctx);
    }
    return true;
  }

  private beginValidation(ctx: DeviceContext): Promise<boolean> {
    ctx.processingState = 'validating';
    return new Promise<boolean>((resolve) => {
      this.validationQueue.push({ ctx, resolve });
    });
  }

  private drainValidationQueue(): void {
    while (this.validationQueue.length > 0) {
      const item = this.validationQueue.shift()!;
      this.validateAndApply(item.ctx, item.resolve);
    }
  }

  private validateAndApply(ctx: DeviceContext, resolve: (v: boolean) => void): void {
    const fullHash = crypto
      .createHash('sha256')
      .update(ctx.firmwareSlot)
      .digest('hex');

    // Simulate async hardware write with callback
    this.scheduleHardwareWrite(ctx, fullHash, (success) => {
      // BUG: ctx.firmwareSlot may have been deallocated by cancelUpload
      // but we still reference it here through the captured ctx
      if (success) {
        ctx.processingState = 'applying';
        const verifyHash = crypto
          .createHash('sha256')
          .update(ctx.firmwareSlot) // Use-after-free: firmwareSlot may be zeroed/reallocated
          .digest('hex');
        if (verifyHash === fullHash) {
          this.emit('firmware-applied', ctx.deviceId);
          resolve(true);
        } else {
          this.emit('firmware-corrupted', ctx.deviceId);
          resolve(false);
        }
      } else {
        ctx.processingState = 'idle';
        resolve(false);
      }
    });
  }

  private scheduleHardwareWrite(
    ctx: DeviceContext,
    _hash: string,
    callback: (success: boolean) => void
  ): void {
    // Simulates async DMA transfer to flash memory
    setTimeout(() => {
      callback(true);
    }, 50);
  }

  cancelUpload(deviceId: string): void {
    const ctx = this.devices.get(deviceId);
    if (!ctx) return;
    // Deallocate the firmware buffer immediately
    ctx.firmwareSlot = Buffer.alloc(0);
    ctx.chunkMap.clear();
    ctx.receivedSize = 0;
    ctx.processingState = 'idle';
    // Note: does NOT remove from devices map, does NOT cancel pending callbacks
  }

  resetDevice(deviceId: string): void {
    const ctx = this.devices.get(deviceId);
    if (!ctx) return;
    ctx.firmwareSlot = Buffer.alloc(0);
    ctx.chunkMap.clear();
    ctx.receivedSize = 0;
    ctx.processingState = 'idle';
    this.devices.delete(deviceId);
  }

  destroy(): void {
    if (this.processingInterval) {
      clearInterval(this.processingInterval);
    }
    // Clear all device contexts
    for (const [id] of this.devices) {
      this.resetDevice(id);
    }
  }
}

export { FirmwareProcessor, FirmwareChunk, DeviceContext };
